import{_ as a,o as t,c as o,a7 as l}from"./chunks/framework.FWlv_suP.js";const p=JSON.parse('{"title":"Office Pulse Data Deletion","description":"Official data-deletion instructions for Office Pulse.","frontmatter":{"title":"Office Pulse Data Deletion","description":"Official data-deletion instructions for Office Pulse.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/office-pulse.md","filePath":"data-deletion/office-pulse.md"}'),r={name:"data-deletion/office-pulse.md"};function s(i,e,d,n,c,f){return t(),o("div",null,[...e[0]||(e[0]=[l('<h1 id="delete-office-pulse-data" tabindex="-1">Delete Office Pulse Data <a class="header-anchor" href="#delete-office-pulse-data" aria-label="Permalink to &quot;Delete Office Pulse Data&quot;">​</a></h1><p>Office Pulse has no general-purpose developer-operated user account.</p><h2 id="delete-local-records" tabindex="-1">Delete local records <a class="header-anchor" href="#delete-local-records" aria-label="Permalink to &quot;Delete local records&quot;">​</a></h2><p>Delete individual tasks, memos, cue cards, reminders, or other editable records from their corresponding screens where a delete action is available. Logging out removes the local successful-login record.</p><p>To remove all local records, clear Office Pulse storage in Android system settings or uninstall the app. In a browser, clear the site&#39;s localStorage, cache, and site data.</p><h2 id="delete-external-records-and-files" tabindex="-1">Delete external records and files <a class="header-anchor" href="#delete-external-records-and-files" aria-label="Permalink to &quot;Delete external records and files&quot;">​</a></h2><p>Clearing app data does not delete:</p><ul><li>Information already submitted to a Google Form</li><li>Rows or source data stored in configured Google Sheets</li><li>PDF reports saved or shared outside Office Pulse</li></ul><p>Delete PDF copies from every destination. Contact the relevant form or sheet owner or workplace administrator to request deletion of externally held data, subject to their retention requirements.</p><p>Because the developer does not hold a general Office Pulse cloud account, emailing support cannot delete records that exist only on your device or in a third party&#39;s Google Workspace.</p>',10)])])}const h=a(r,[["render",s]]);export{p as __pageData,h as default};
